# ============================================================================
# Dead Arrival map: HOLLOW LINE
# A great war trench network with two deep bunkers. You can never leave
# the line: there are no stairs up, the parapets are too tall to climb.
# spawn_mode = drop  -> zombies drop in from the parapets above
# ============================================================================
name = Hollow Line
desc = They come from above
author = Faded Dream
spawn_mode = drop
ambient = 150 142 128
sky = 24 25 27
player_spawn = -15 -2.65 0 180

